1	export type Cell = [x: number, y: number];
2	
3	// A cell's identity is its position, but arrays compare by reference, so the
4	// same position reached twice is two distinct values. This key restores
5	// identity: equal positions produce equal keys.
6	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
7	
8	// Membership test for the current generation, closed over its own index.
9	type LiveSet = (cell: Cell) => boolean;
10	
11	const OFFSETS = [-1, 0, 1];
12	
13	const neighborsOf = ([x, y]: Cell): Cell[] =>
14	  OFFSETS.flatMap((dx) =>
15	    OFFSETS.filter((dy) => dx !== 0 || dy !== 0).map(
16	      (dy): Cell => [x + dx, y + dy],
17	    ),
18	  );
19	
20	const countLiveNeighbors = (cell: Cell, isLive: LiveSet): number =>
21	  neighborsOf(cell).filter(isLive).length;
22	
23	// Fewer than 2 neighbors is underpopulation, more than 3 is overpopulation;
24	// both are death. Only this band survives.
25	const MIN_NEIGHBORS_TO_SURVIVE = 2;
26	const MAX_NEIGHBORS_TO_SURVIVE = 3;
27	
28	const survives = (liveNeighborCount: number): boolean =>
29	  liveNeighborCount >= MIN_NEIGHBORS_TO_SURVIVE &&
30	  liveNeighborCount <= MAX_NEIGHBORS_TO_SURVIVE;
31	
32	const NEIGHBORS_TO_BE_BORN = 3;
33	
34	const isBorn = (liveNeighborCount: number): boolean =>
35	  liveNeighborCount === NEIGHBORS_TO_BE_BORN;
36	
37	const liveSet = (liveCells: Cell[]): LiveSet => {
38	  const keys = new Set(liveCells.map(keyOf));
39	  return (cell) => keys.has(keyOf(cell));
40	};
41	
42	const deduplicate = (cells: Cell[]): Cell[] => [
43	  ...new Map(cells.map((cell) => [keyOf(cell), cell])).values(),
44	];
45	
46	// Only cells touching a live cell can change state, so the rest of the
47	// infinite grid never needs to be examined.
48	const cellsToEvaluate = (liveCells: Cell[]): Cell[] =>
49	  deduplicate(liveCells.flatMap((cell) => [cell, ...neighborsOf(cell)]));
50	
51	export function nextGeneration(liveCells: Cell[]): Cell[] {
52	  const isLive = liveSet(liveCells);
53	  return cellsToEvaluate(liveCells).filter((cell) => {
54	    const liveNeighborCount = countLiveNeighbors(cell, isLive);
55	    return isLive(cell)
56	      ? survives(liveNeighborCount)
57	      : isBorn(liveNeighborCount);
58	  });
59	}
