1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - nextGeneration", () => {
5	  it("returns an empty grid for an empty grid — [] → []", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	
9	  it("Rule 1 (underpopulation): a single live cell with 0 neighbors dies — [(0,0)] → []", () => {
10	    expect(nextGeneration([[0, 0]])).toEqual([]);
11	  });
12	
13	  it("Rule 1 (underpopulation): two adjacent live cells each with 1 neighbor die — [(0,1), (1,1)] → []", () => {
14	    expect(
15	      nextGeneration([
16	        [0, 1],
17	        [1, 1],
18	      ]),
19	    ).toEqual([]);
20	  });
21	
22	  it("Rule 2 (survival): a live cell with 2 live neighbors lives on — blinker [(0,0), (0,1), (0,2)] keeps (0,1) alive", () => {
23	    expect(
24	      nextGeneration([
25	        [0, 0],
26	        [0, 1],
27	        [0, 2],
28	      ]),
29	    ).toContainEqual([0, 1]);
30	  });
31	
32	  // NOTE: the spec's Rule 2 illustration (### / ... / .#. → .#. / .#. / ...) is
33	  // internally inconsistent: in its own Gen 0 drawing the cell (1,1) is dead and
34	  // has 4 neighbors, not the 3 the prose claims, and the drawn Gen 1 is not what
35	  // Conway's rules produce from the drawn Gen 0. The 3-neighbor survival branch is
36	  // therefore pinned here with an unambiguous configuration — in a 2x2 block every
37	  // live cell has exactly 3 live neighbors and survives.
38	  it("Rule 2 (survival): a live cell with 3 live neighbors lives on — (0,0) in a 2x2 block has 3 neighbors and survives", () => {
39	    expect(
40	      nextGeneration([
41	        [0, 0],
42	        [1, 0],
43	        [0, 1],
44	        [1, 1],
45	      ]),
46	    ).toContainEqual([0, 0]);
47	  });
48	
49	  // NOTE: like the Rule 2 illustration, the spec's Rule 3 drawing
50	  // (### / .#. / ### → #.# / #.# / #.#) is internally inconsistent. In its own
51	  // Gen 0 the center (1,1) has SIX live neighbors, not the 4 the prose claims,
52	  // and the true next generation spills to y=-1 and y=3 rather than being the
53	  // drawn 3x3. The rule itself is sound and is what gets pinned here: (1,1) is
54	  // alive with more than 3 neighbors, so it dies.
55	  it("Rule 3 (overpopulation): a live cell with more than 3 live neighbors dies — center of ### / .#. / ### has 6 and dies", () => {
56	    expect(
57	      nextGeneration([
58	        [0, 0],
59	        [1, 0],
60	        [2, 0],
61	        [1, 1],
62	        [0, 2],
63	        [1, 2],
64	        [2, 2],
65	      ]),
66	    ).not.toContainEqual([1, 1]);
67	  });
68	
69	  it("Rule 4 (reproduction): a dead cell with exactly 3 live neighbors becomes alive — ##. / #.. / ... → ##. / ##. / ...", () => {
70	    const result = nextGeneration([
71	      [0, 0],
72	      [1, 0],
73	      [0, 1],
74	    ]);
75	
76	    expect(result).toEqual(
77	      expect.arrayContaining([
78	        [0, 0],
79	        [1, 0],
80	        [0, 1],
81	        [1, 1],
82	      ]),
83	    );
84	    expect(result).toHaveLength(4);
85	  });
86	
87	  it("handles negative coordinates — blinker [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]", () => {
88	    const result = nextGeneration([
89	      [0, 0],
90	      [0, 1],
91	      [0, 2],
92	    ]);
93	
94	    expect(result).toEqual(
95	      expect.arrayContaining([
96	        [-1, 1],
97	        [0, 1],
98	        [1, 1],
99	      ]),
100	    );
101	    expect(result).toHaveLength(3);
102	  });
103	
104	  it.todo(
105	    "block still life stays unchanged — [(0,0), (1,0), (0,1), (1,1)] → same four cells",
106	  );
107	
108	  it.todo(
109	    "blinker oscillates back to vertical after two generations — [(-1,1), (0,1), (1,1)] → [(0,0), (0,1), (0,2)]",
110	  );
111	});
